-- The TOP-GRIP code key (Code keys -> Parting -> TOP-GRIP), from the ISCAR
-- e-catalog's TOP-GRIP families (TGMF / TGMP / TGMA inserts, TGDR/L, TGHN,
-- TGIR/L tools); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.topgrip', $ck${"title": "TOP-GRIP code key – inserts and tools", "subtitle": "Utility double-ended inserts (TGMF / TGMP / TGMA) for external and internal grooving and turning, and their holders, blades and bars", "example": "TGMF 302", "decoder": "top-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "TGMF", "rows": [{"code": "TGMF", "meaning": "Utility double-ended inserts for external and internal grooving and turning (full radius: profiling)"}, {"code": "TGMP", "meaning": "Utility double-ended inserts, P version (inferred)"}, {"code": "TGMA", "meaning": "Utility double-ended inserts for grooving and turning cast iron"}]}, {"key": "i-width", "title": "Insert – cutting width and corner radius", "sample": "302", "rows": [{"code": "###", "meaning": "Width and corner radius x10 (e.g. 302 = 3 mm, R0.2; 315 = 3 mm, R1.5 full radius)"}, {"code": "###-###", "meaning": "Width and corner radius x100 (e.g. 635-080 = 6.35 mm, R0.80)"}]}, {"key": "i-variant", "title": "Insert – variant", "rows": [{"code": "K", "meaning": "For cast iron (TGMA)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "TGD", "meaning": "External holders for turning, grooving and profiling (TGDR / TGDL)"}, {"code": "TGH", "meaning": "Blades carrying utility inserts (TGHN-D double-ended, -S single-ended, 26-M internal for GHIC...-70 bars)"}, {"code": "TGI", "meaning": "Grooving and turning bars with coolant holes (TGIR / TGIL-C)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}, {"code": "R/L", "meaning": "Right- or left-hand"}, {"code": "N", "meaning": "Neutral"}, {"code": "RE", "meaning": "Right-hand, E type (RE/LE adapters) (inferred)"}, {"code": "LE", "meaning": "Left-hand, E type (RE/LE adapters) (inferred)"}, {"code": "R/LE", "meaning": "Right- or left-hand, E type (inferred)"}]}, {"key": "t-angle", "title": "Tool – angle a° (multi-spindle blades)", "rows": [{"code": "#", "meaning": "Angle a° (0 or 5)"}]}, {"key": "t-height", "title": "Tool – blade height / shank", "rows": [{"code": "##", "meaning": "Blade height or shank size in mm (e.g. 26, 32)"}, {"code": "###", "meaning": "Blade height in mm (e.g. 100, 150)"}, {"code": "####", "meaning": "Shank height x width in mm (e.g. 2525 = 25 x 25)"}]}, {"key": "t-width", "title": "Tool – insert width (seat)", "rows": [{"code": "#", "meaning": "Insert width in mm (the seat's insert, e.g. 3)"}]}, {"key": "t-dia", "title": "Tool – D size", "rows": [{"code": "D##", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D24, D52) (inferred)"}, {"code": "D###", "meaning": "Maximum cutting diameter / adapter size in mm (e.g. D120) (inferred)"}]}, {"key": "t-pockets", "title": "Tool – pockets", "rows": [{"code": "#Z", "meaning": "Number of pockets (e.g. 2Z, 4Z)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "JHP", "meaning": "Channels for high-pressure coolant"}, {"code": "MC", "meaning": "Bottom inlets for the high-pressure coolant"}, {"code": "K", "meaning": "With coolant holes (10 bar min.; cooling tube SGCU 341 ordered separately)"}, {"code": "C", "meaning": "With coolant – frontal coolant holes (JETCUT) / internal coolant"}, {"code": "XL", "meaning": "Extra long"}, {"code": "SH", "meaning": "Short head (CNC and Swiss automatics)"}, {"code": "S", "meaning": "Single-sided blade (e.g. TGFH-S) / for next to high shoulders (e.g. PCHRS)"}, {"code": "IQ", "meaning": "IQ line (e.g. TGTR/L-IQ, PCHR/L-D-IQ)"}, {"code": "TR", "meaning": "For TRAUB and Index machines"}, {"code": "MB", "meaning": "For other manufacturers' blocks"}, {"code": "B", "meaning": "B type, e.g. DGTR/L-B-D (reinforced) / DGAD-B-D (screw-clamped) (inferred)"}, {"code": "L###", "meaning": "Tool length in mm (e.g. L120)"}, {"code": "D", "meaning": "Double-ended blade"}, {"code": "M", "meaning": "For TOP-GRIP utility inserts (TGDR/L, TGHN 26-M internal blades) (inferred)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
